CREATE DATABASE IF NOT EXISTS pos_supermarket;
USE pos_supermarket;
CREATE TABLE users (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(160) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('CASHIER','MANAGER') NOT NULL DEFAULT 'CASHIER', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id CHAR(36) PRIMARY KEY, sku VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, category VARCHAR(80) NOT NULL, price DECIMAL(10,2) NOT NULL, tax_rate DECIMAL(5,2) NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE inventory (product_id CHAR(36) PRIMARY KEY, quantity INT NOT NULL DEFAULT 0, reorder_level INT NOT NULL DEFAULT 10, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE discounts (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, type ENUM('PERCENT','FIXED') NOT NULL, value DECIMAL(10,2) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL);
CREATE TABLE sales (id CHAR(36) PRIMARY KEY, receipt_number VARCHAR(40) UNIQUE NOT NULL, cashier_id CHAR(36) NOT NULL, subtotal DECIMAL(10,2) NOT NULL, discount_total DECIMAL(10,2) NOT NULL DEFAULT 0, tax_total DECIMAL(10,2) NOT NULL DEFAULT 0, total DECIMAL(10,2) NOT NULL, status ENUM('COMPLETED','RETURNED','VOID') NOT NULL DEFAULT 'COMPLETED', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (cashier_id) REFERENCES users(id));
CREATE TABLE sale_items (id CHAR(36) PRIMARY KEY, sale_id CHAR(36) NOT NULL, product_id CHAR(36) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, line_total DECIMAL(10,2) NOT NULL, FOREIGN KEY (sale_id) REFERENCES sales(id), FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE payments (id CHAR(36) PRIMARY KEY, sale_id CHAR(36) NOT NULL, method ENUM('CASH','CARD','MOBILE_MONEY','QR') NOT NULL, amount DECIMAL(10,2) NOT NULL, reference VARCHAR(120), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (sale_id) REFERENCES sales(id));
CREATE TABLE returns (id CHAR(36) PRIMARY KEY, sale_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, reason VARCHAR(255) NOT NULL, amount DECIMAL(10,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (sale_id) REFERENCES sales(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX idx_sales_created_at ON sales(created_at);
CREATE INDEX idx_products_name ON products(name);
